class Operation {
 public:
  Operation(AbstractMatcher *matcher, Method method) : matcher_(matcher), method_(method) { }
  void init(AbstractMatcher *matcher, Method method) { matcher_ = matcher; method_ = method; }
  size_t operator()() const { return matcher_->match(method_); }
  iterator begin() const { return iterator(matcher_, method_); }
  iterator end() const { return iterator(); }
  const_iterator cbegin() const { return const_iterator(matcher_, method_); }
  const_iterator cend() const { return const_iterator(); }
 private:
  AbstractMatcher *matcher_;
  Method           method_;
};

