class Bits {
 public:
  static const size_t npos = static_cast<size_t>(-1);
  struct Bitref {
    Bitref(
        size_t    n,
        uint64_t *p)
      :
        m(1ULL << n),
        p(p)
    { }
    uint64_t  m;
    uint64_t *p;
    operator bool() const
    {
      return (*p & m) != 0;
    }
    const Bitref& operator=(bool b) const
    {
      if (b)
        *p |= m;
      else
        *p &= ~m;
      return *this;
    }
    bool operator|=(bool b) const
    {
      if (b)
        *p |= m;
      return (*p & m) != 0;
    }
    bool operator&=(bool b) const
    {
      if (!b)
        *p &= ~m;
      return (*p & m) != 0;
    }
    bool operator^=(bool b) const
    {
      if (b)
        *p ^= m;
      return (*p & m) != 0;
    }
  };
  Bits()
    :
      len_(0),
      vec_(NULL)
  { }
  Bits(const Bits& bits)
  {
    operator=(bits);
  }
  Bits(size_t n)
    :
      len_(0),
      vec_(NULL)
  {
    insert(n);
  }
  Bits(
      size_t n1,
      size_t n2)
    :
      len_(0),
      vec_(NULL)
  {
    insert(n1, n2);
  }
  ~Bits()
  {
    if (vec_)
      delete[] vec_;
  }
  Bits& operator=(const Bits& bits)
  {
    len_ = bits.len_;
    if (len_)
      std::memcpy(vec_ = new uint64_t[len_], bits.vec_, len_ << 3);
    else
      vec_ = NULL;
    return *this;
  }
  Bitref operator[](size_t n)
  {
    alloc((n >> 6) + 1);
    return Bitref(n & 0x3F, &vec_[n >> 6]);
  }
  bool operator[](size_t n) const
  {
    return n >> 6 < len_ && (vec_[n >> 6] & 1ULL << (n & 0x3F)) != 0;
  }
  Bits& insert(size_t n)
  {
    alloc((n >> 6) + 1);
    vec_[n >> 6] |= 1ULL << (n & 0x3F);
    return *this;
  }
  Bits& erase(size_t n)
  {
    if (n >> 6 < len_)
      vec_[n >> 6] &= ~(1ULL << (n & 0x3F));
    return *this;
  }
  Bits& flip(size_t n)
  {
    alloc((n >> 6) + 1);
    vec_[n >> 6] ^= 1ULL << (n & 0x3F);
    return *this;
  }
  Bits& insert(
      size_t n1,
      size_t n2)
  {
    alloc((n2 >> 6) + 1);
    for (size_t i = n1; i <= n2; ++i)
      vec_[i >> 6] |= 1ULL << (i & 0x3F);
    return *this;
  }
  Bits& erase(
      size_t n1,
      size_t n2)
  {
    if (n1 >> 6 < len_)
    {
      if (n2 >> 6 >= len_)
        n2 = (len_ - 1) << 6;
      for (size_t i = n1; i <= n2; ++i)
        vec_[i >> 6] &= ~(1ULL << (i & 0x3F));
    }
    return *this;
  }
  Bits& flip(
      size_t n1,
      size_t n2)
  {
    alloc((n2 >> 6) + 1);
    for (size_t i = n1; i <= n2; ++i)
      vec_[i >> 6] ^= 1ULL << (i & 0x3F);
    return *this;
  }
  Bits& lshift()
  {
    if (len_ > 0)
    {
      uint64_t lo = 0;
      for (size_t i = 0; i < len_; ++i)
      {
        uint64_t hi = vec_[i] & (1ULL << 63);
        vec_[i] = (vec_[i] << 1) | lo;
        lo = hi >> 63;
      }
      if (lo)
      {
        alloc(len_ + 1);
        vec_[len_ - 1] = 1;
      }
    }
    return *this;
  }
  Bits& rshift()
  {
    uint64_t hi = 0;
    for (size_t i = 1; i <= len_; ++i)
    {
      uint64_t lo = vec_[len_ - i] & 1;
      vec_[len_ - i] = (vec_[len_ - i] >> 1) | hi;
      hi = lo << 63;
    }
    return *this;
  }
  Bits& operator|=(const Bits& bits)
  {
    alloc(bits.len_);
    for (size_t i = 0; i < bits.len_; ++i)
      vec_[i] |= bits.vec_[i];
    return *this;
  }
  Bits& operator&=(const Bits& bits)
  {
    alloc(bits.len_);
    for (size_t i = 0; i < bits.len_; ++i)
      vec_[i] &= bits.vec_[i];
    for (size_t i = bits.len_; i < len_; ++i)
      vec_[i] = 0;
    return *this;
  }
  Bits& operator^=(const Bits& bits)
  {
    alloc(bits.len_);
    for (size_t i = 0; i < bits.len_; ++i)
      vec_[i] ^= bits.vec_[i];
    return *this;
  }
  Bits& operator-=(const Bits& bits)
  {
    size_t k = len_;
    if (bits.len_ < k)
      k = bits.len_;
    for (size_t i = 0; i < k; ++i)
      vec_[i] = (vec_[i] | bits.vec_[i]) - bits.vec_[i];
    return *this;
  }
  Bits operator|(const Bits& bits) const
  {
    return Bits(*this) |= bits;
  }
  Bits operator&(const Bits& bits) const
  {
    return Bits(*this) &= bits;
  }
  Bits operator^(const Bits& bits) const
  {
    return Bits(*this) ^= bits;
  }
  Bits operator-(const Bits& bits) const
  {
    return Bits(*this) -= bits;
  }
  Bits operator~() const
  {
    return Bits(*this).flip();
  }
  bool operator==(const Bits& bits) const
  {
    size_t k = len_;
    if (bits.len_ < k)
      k = bits.len_;
    for (size_t i = 0; i < k; ++i)
      if (vec_[i] != bits.vec_[i])
        return false;
    for (size_t i = bits.len_; i < len_; ++i)
      if (vec_[i] != 0)
        return false;
    for (size_t i = len_; i < bits.len_; ++i)
      if (bits.vec_[i] != 0)
        return false;
    return true;
  }
  bool operator!=(const Bits& bits) const
  {
    return !operator==(bits);
  }
  bool operator<(const Bits& bits) const
  {
    size_t k = len_;
    if (bits.len_ < k)
      k = bits.len_;
    for (size_t i = 0; i < k; ++i)
    {
      if (vec_[i] < bits.vec_[i])
        return true;
      if (vec_[i] > bits.vec_[i])
        return false;
    }
    for (size_t i = bits.len_; i < len_; ++i)
      if (vec_[i] != 0)
        return false;
    for (size_t i = len_; i < bits.len_; ++i)
      if (bits.vec_[i] != 0)
        return true;
    return false;
  }
  bool operator>(const Bits& bits) const
  {
    return bits.operator<(*this);
  }
  bool operator<=(const Bits& bits) const
  {
    return !operator>(bits);
  }
  bool operator>=(const Bits& bits) const
  {
    return !operator<(bits);
  }
  bool all() const
  {
    for (size_t i = 0; i < len_; ++i)
      if (vec_[i] + 1 != 0)
        return false;
    return true;
  }
  bool any() const
  {
    for (size_t i = 0; i < len_; ++i)
      if (vec_[i] != 0)
        return true;
    return false;
  }
  Bits& clear()
  {
    if (vec_)
      std::memset(vec_, 0, len_ << 3);
    return *this;
  }
  Bits& flip()
  {
    for (size_t i = 0; i < len_; ++i)
      vec_[i] = ~vec_[i];
    return *this;
  }
  Bits& reserve(size_t len)
  {
    if (len)
      alloc(((len - 1) >> 6) + 1);
    return *this;
  }
  size_t size() const
  {
    return len_ << 6;
  }
  size_t count() const
  {
    size_t n = 0, k = 0;
    while ((n = find_first(n)) != npos)
      ++n, ++k;
    return k;
  }
  bool intersects(const Bits& bits) const
  {
    size_t k = len_;
    if (bits.len_ < k)
      k = bits.len_;
    for (size_t i = 0; i < k; ++i)
      if (vec_[i] & bits.vec_[i])
        return true;
    return false;
  }
  bool contains(const Bits& bits) const
  {
    size_t k = len_;
    if (bits.len_ < k)
      k = bits.len_;
    for (size_t i = 0; i < k; ++i)
      if (vec_[i] != (vec_[i] | bits.vec_[i]))
        return false;
    for (size_t i = len_; i < bits.len_; ++i)
      if (bits.vec_[i] != 0)
        return false;
    return true;
  }
  size_t find_first(size_t n = 0) const
  {
    size_t i = n >> 6;
    if (i < len_ && vec_[i])
      for (size_t j = n & 0x3F; j < 64; ++j)
        if (vec_[i] & 1ULL << j)
          return (i << 6) + j;
    for (i = i + 1; i < len_; ++i)
      if (vec_[i])
        for (size_t j = 0; j < 64; ++j)
          if (vec_[i] & 1ULL << j)
            return (i << 6) + j;
    return npos;
  }
  size_t find_next(size_t n) const
  {
    return find_first(n + 1);
  }
  void swap(Bits& bits)
  {
    size_t k = len_;
    uint64_t *p = vec_;
    len_ = bits.len_;
    vec_ = bits.vec_;
    bits.len_ = k;
    bits.vec_ = p;
  }
 private:
  void alloc(size_t len)
  {
    if (len > len_)
    {
      size_t k = 1;
      while (k < len)
        k <<= 1;
      uint64_t *p = new uint64_t[k]();
      if (vec_)
      {
        std::memcpy(p, vec_, len_ << 3);
        delete[] vec_;
      }
      len_ = k;
      vec_ = p;
    }
  }
  size_t    len_;
  uint64_t *vec_;
};

