class LineMatcher : public AbstractMatcher {
 public:
  LineMatcher(
      const Input& input = Input(),
      const char  *opt = NULL)
    :
      AbstractMatcher(input, opt),
      inc_(false)
  { }
  LineMatcher(const LineMatcher& matcher)
    :
      AbstractMatcher(matcher.in, matcher.opt_),
      inc_(false)
  { }
  virtual ~LineMatcher()
  { }
  LineMatcher& operator=(const LineMatcher& matcher)
  {
    AbstractMatcher::operator=(matcher);
    inc_ = matcher.inc_;
    return *this;
  }
  virtual LineMatcher *clone() REFLEX_OVERRIDE
  {
    return new LineMatcher(*this);
  }
  virtual void reset(const char *opt = NULL) REFLEX_OVERRIDE
  {
    DBGLOG("LineMatcher::reset()");
    AbstractMatcher::reset(opt);
    inc_ = false;
  }
  virtual std::pair<const char*,size_t> operator[](size_t) const REFLEX_OVERRIDE
  {
    return std::pair<const char*,size_t>(txt_, len_);
  }
  virtual std::pair<size_t,const char*> group_id() REFLEX_OVERRIDE
  {
    return std::pair<size_t,const char*>(0, static_cast<const char*>(NULL));
  }
  virtual std::pair<size_t,const char*> group_next_id() REFLEX_OVERRIDE
  {
    return std::pair<size_t,const char*>(0, static_cast<const char*>(NULL));
  }
 protected:
  virtual size_t match(Method method) REFLEX_OVERRIDE
  {
    DBGLOG("BEGIN LineMatcher::match(%d)", method);
    reset_text();
    got_ = '\n';
find:
    pos_ += inc_;
    txt_ = buf_ + pos_;
    cur_ = txt_ - buf_;
    len_ = 0;
    cap_ = !at_end();
    if (cap_)
    {
      inc_ = false;
      const char *end = eol(true);
      if (end == txt_)
        return cap_ = 0;
      pos_ = end - buf_;
      len_ = end - txt_;
      size_t n;
      switch (method)
      {
        case Const::SCAN:
          break;
        case Const::FIND:
          n = len_ - (*--end == '\n');
          if (!opt_.A)
          {
            inc_ = (len_ > n);
            len_ = n;
            pos_ = cur_ + n;
          }
          if (n == 0 && !opt_.N)
            goto find;
          if (n > 0 && opt_.X)
            goto find;
          break;
        case Const::SPLIT:
          txt_ += len_ - (*--end == '\n');
          cur_ = txt_ - buf_;
          len_ = pos_ - cur_;
          break;
        case Const::MATCH:
          cap_ = eof_;
          break;
      }
    }
    return cap_;
  }
  bool inc_;
};

