namespace reflex {

class FuzzyMatcher : public Matcher {
 public:
  static const uint16_t INS = 0x1000;
  static const uint16_t DEL = 0x2000;
  static const uint16_t SUB = 0x4000;
  static const uint16_t BIN = 0x8000;
  FuzzyMatcher()
    :
      Matcher()
  {
    distance(1);
  }
  template<typename P>
  FuzzyMatcher(
      const P     *pattern,
      const Input& input = Input(),
      const char  *opt = NULL)
    :
      Matcher(pattern, input, opt)
  {
    distance(1);
  }
  template<typename P>
  FuzzyMatcher(
      const P     *pattern,
      uint16_t     max,
      const Input& input = Input(),
      const char  *opt = NULL)
    :
      Matcher(pattern, input, opt)
  {
    distance(max);
  }
  template<typename P>
  FuzzyMatcher(
      const P&     pattern,
      const Input& input = Input(),
      const char  *opt = NULL)
    :
      Matcher(pattern, input, opt)
  {
    distance(1);
  }
  template<typename P>
  FuzzyMatcher(
      const P&     pattern,
      uint16_t     max,
      const Input& input = Input(),
      const char  *opt = NULL)
    :
      Matcher(pattern, input, opt)
  {
    distance(max);
  }
  FuzzyMatcher(const FuzzyMatcher& matcher)
    :
      Matcher(matcher),
      max_(matcher.max_),
      err_(0),
      ins_(matcher.ins_),
      del_(matcher.del_),
      sub_(matcher.sub_),
      bin_(matcher.bin_)
  {
    DBGLOG("FuzzyMatcher::FuzzyMatcher(matcher)");
    bpt_.resize(max_);
  }
  using Matcher::operator=;
  virtual FuzzyMatcher& operator=(const FuzzyMatcher& matcher)
  {
    Matcher::operator=(matcher);
    max_ = matcher.max_;
    err_ = 0;
    ins_ = matcher.ins_;
    del_ = matcher.del_;
    sub_ = matcher.sub_;
    bin_ = matcher.bin_;
    bpt_.resize(max_);
    return *this;
  }
  virtual FuzzyMatcher *clone() REFLEX_OVERRIDE
  {
    return new FuzzyMatcher(*this);
  }
  uint8_t edits() const
  {
    return err_;
  }
  void distance(uint16_t max)
  {
    max_ = static_cast<uint8_t>(max);
    err_ = 0;
    ins_ = ((max & (INS | DEL | SUB)) == 0 || (max & INS));
    del_ = ((max & (INS | DEL | SUB)) == 0 || (max & DEL));
    sub_ = ((max & (INS | DEL | SUB)) == 0 || (max & SUB));
    bin_ = (max & BIN);
    bpt_.resize(max_);
  }
  uint16_t distance()
  {
    return max_;
  }
 protected:
  struct SaveState {
    SaveState(size_t ded)
      :
        use(false),
        loc(0),
        cap(0),
        txt(0),
        cur(0),
        pos(0),
        ded(ded),
        mrk(false),
        err(0)
    { }
    bool    use;
    size_t  loc;
    size_t  cap;
    size_t  txt;
    size_t  cur;
    size_t  pos;
    size_t  ded;
    bool    mrk;
    uint8_t err;
  };
  struct BacktrackPoint {
    BacktrackPoint()
      :
        pc0(NULL),
        pc1(NULL),
        len(0),
        err(0),
        alt(true),
        sub(true)
    { }
    const Pattern::Opcode *pc0;
    const Pattern::Opcode *pc1;
    size_t                 len;
    uint8_t                err;
    bool                   alt;
    bool                   sub;
  };
  void point(BacktrackPoint& bpt, const Pattern::Opcode *pc, size_t len, bool alternate = true, bool eof = false)
  {
    while (!Pattern::is_opcode_goto(*pc))
      ++pc;
    bpt.pc0 = pc;
    bpt.pc1 = pc;
    bpt.len = len - !eof;
    bpt.err = err_;
    bpt.alt = sub_ && alternate;
    bpt.sub = bpt.alt;
  }
  const Pattern::Opcode *backtrack(BacktrackPoint& bpt, int& ch)
  {
    if (bpt.pc1 == NULL)
      return NULL;
    if (!Pattern::is_opcode_goto(*bpt.pc1))
      return bpt.pc1 = NULL;
    Pattern::Index jump = Pattern::index_of(*bpt.pc1);
    if (jump == Pattern::Const::HALT)
    {
      if (bin_ || !Pattern::is_opcode_goto(*bpt.pc0) || (Pattern::lo_of(*bpt.pc0) & 0xC0) != 0xC0 || (Pattern::hi_of(*bpt.pc0) & 0xC0) != 0xC0)
        return bpt.pc1 = NULL;
      for (int i = 0; i < 3; ++i)
      {
        jump = Pattern::index_of(*bpt.pc0);
        if (jump == Pattern::Const::HALT || pat_->opc_ + jump == bpt.pc0)
          return bpt.pc1 = NULL;
        if (jump == Pattern::Const::LONG)
          jump = Pattern::long_index_of(bpt.pc0[1]);
        const Pattern::Opcode *pc0 = pat_->opc_ + jump;
        const Pattern::Opcode *pc1 = pc0;
        while (!Pattern::is_opcode_goto(*pc1))
          ++pc1;
        if (Pattern::is_meta(Pattern::lo_of(*pc1)) || ((Pattern::lo_of(*pc1) & 0xC0) != 0x80 && (Pattern::hi_of(*pc1) & 0xC0) != 0x80))
          break;
        bpt.pc0 = pc0;
        bpt.pc1 = pc1;
      }
      jump = Pattern::index_of(*bpt.pc1);
      if (jump == Pattern::Const::HALT)
        return bpt.pc1 = NULL;
      if (jump == Pattern::Const::LONG)
        jump = Pattern::long_index_of(*++bpt.pc1);
      bpt.sub = bpt.alt;
      DBGLOG("Multibyte jump to %u", jump);
    }
    else if (jump == Pattern::Const::LONG)
    {
      jump = Pattern::long_index_of(*++bpt.pc1);
    }
    err_ = bpt.err;
    pos_ = (txt_ - buf_) + bpt.len;
    if (pos_ > 0)
      ch = static_cast<unsigned char>(buf_[pos_ - 1]);
    else
      ch = got_;
    if (bpt.sub)
    {
      DBGLOG("Substitute: jump to %u at pos %zu char %d (0x%x)", jump, pos_, ch, ch);
      int c = get();
      if (!bin_ && c != EOF)
      {
        if (c >= 0xC0)
        {
          int n = (c >= 0xE0) + (c >= 0xF0);
          while (n-- >= 0)
            if ((c = get()) == EOF)
              break;
        }
        else
        {
          while ((peek() & 0xC0) == 0x80)
            if ((c = get()) == EOF)
              break;
        }
      }
      bpt.sub = false;
      bpt.pc1 += !bpt.alt;
    }
    else if (del_)
    {
      DBGLOG("Delete: jump to %u at pos %zu char %d (0x%x)", jump, pos_, ch, ch);
      bpt.sub = bpt.alt;
      ++bpt.pc1;
    }
    else
    {
      return NULL;
    }
    return pat_->opc_ + jump;
  }
  virtual size_t match(Method method) REFLEX_OVERRIDE;
  std::vector<BacktrackPoint> bpt_;
  uint8_t max_;
  uint8_t err_;
  bool ins_;
  bool del_;
  bool sub_;
  bool bin_;
};

