import random
import string

# This generator focuses on producing valid and interesting RE/flex-compatible
# regular expressions, paired with small data payloads when consumed by FUZZ_PARAM_STR.
# Many stubs expect two strings: a regex and an input. This generator returns a single
# bytes buffer. The harness will split it into multiple FUZZ_PARAM_STR() calls, so we
# interleave regexes and inputs separated with newlines. We keep entries short and valid.

# Strategy:
# - Produce a sequence of regex patterns exercising literals, char classes, groups,
#   alternation, quantifiers, anchors, word boundaries, Unicode escapes, and options.
# - Interleave with input strings likely to match or partially match those patterns.
# - Keep total under 4096 bytes.
# - Ensure ASCII/UTF-8 well-formedness and balanced constructs.

ALNUM = string.ascii_letters + string.digits
WHITES = " \t\r\n\f\v"

# Some useful literal building blocks
WORDS = [
    "hello", "world", "abc", "xyz", "test", "regex", "Reflex", "Unicode", "Καλημέρα",
    "mañana", "über", "東京", "🙂", "foo", "bar", "baz", "lorem", "ipsum"
]

def rand_word(rng: random.Random) -> str:
    # Mix ASCII and some UTF-8 words
    if rng.random() < 0.6:
        return rng.choice(WORDS)
    # Synthesize a random ASCII word
    n = rng.randint(1, 10)
    return ''.join(rng.choice(ALNUM) for _ in range(n))

def rand_class(rng: random.Random) -> str:
    # Build a safe character class
    pieces = []
    # include ranges and escapes
    if rng.random() < 0.7:
        pieces.append("a-z")
    if rng.random() < 0.5:
        pieces.append("A-Z")
    if rng.random() < 0.5:
        pieces.append("0-9")
    if rng.random() < 0.3:
        pieces.append("_\s")
    if rng.random() < 0.3:
        pieces.append("[:alpha:]")
    if rng.random() < 0.3:
        pieces.append("[:digit:]")
    if not pieces:
        pieces = ["a-z"]
    inside = ''.join(pieces)
    if rng.random() < 0.2:
        return f"[^{inside}]"  # negated
    return f"[{inside}]"

def rand_quant(rng: random.Random) -> str:
    q = rng.random()
    if q < 0.2:
        return "?"
    if q < 0.4:
        return "+"
    if q < 0.6:
        return "*"
    if q < 0.8:
        a = rng.randint(0, 3)
        b = rng.randint(a, a + 5)
        return f"{{{a},{b}}}"
    else:
        n = rng.randint(1, 5)
        return f"{{{n}}}"

def rand_anchor(rng: random.Random) -> str:
    return rng.choice(["^", "\n^", "\A", "\b", "\B", "", "^?".replace("?", "")])

def rand_group(rng: random.Random, inner: str) -> str:
    kind = rng.random()
    if kind < 0.2:
        return f"(?:{inner})"  # non-capturing
    if kind < 0.35:
        return f"(?i:{inner})"  # case-insensitive group
    if kind < 0.45:
        return f"(?m:{inner})"  # multiline group
    if kind < 0.55:
        return f"(?s:{inner})"  # dotall group
    return f"({inner})"  # capturing

def rand_alt(rng: random.Random, parts) -> str:
    return "|".join(parts)

def rand_escape(rng: random.Random) -> str:
    return rng.choice(["\\d", "\\D", "\\w", "\\W", "\\s", "\\S", "\\l", "\\u", ".", "\\n", "\\t"])

def rand_utf_escape(rng: random.Random) -> str:
    # Produce valid \uXXXX or \xHH escapes
    if rng.random() < 0.5:
        val = rng.randint(0, 0xFFFF)
        return f"\\u{val:04X}"
    else:
        val = rng.randint(0, 0xFF)
        return f"\\x{val:02X}"

def build_regex(rng: random.Random) -> str:
    parts = []
    # Optional anchors
    if rng.random() < 0.5:
        parts.append("^")
    # Build 2-4 segments
    segs = rng.randint(2, 4)
    for _ in range(segs):
        choice = rng.random()
        if choice < 0.25:
            seg = rand_class(rng)
        elif choice < 0.45:
            seg = rand_escape(rng)
        elif choice < 0.65:
            # small literal, escape any special chars
            lit = rand_word(rng)
            # Escape regex metachars in lit minimally
            lit = ''.join((c if c.isalnum() else '\\' + c) for c in lit)
            seg = lit
        elif choice < 0.8:
            seg = rand_utf_escape(rng)
        else:
            # alternation of simple atoms
            a = rand_word(rng)
            b = rand_word(rng)
            c = rand_word(rng)
            options = [a, b, c]
            seg = rand_group(rng, rand_alt(rng, options))
        # Occasionally group and quantify
        if rng.random() < 0.6:
            seg = rand_group(rng, seg)
        if rng.random() < 0.7:
            seg += rand_quant(rng)
        parts.append(seg)
    if rng.random() < 0.5:
        parts.append("$")
    regex = ''.join(parts)
    # Constrain length
    if len(regex) > 128:
        regex = regex[:128]
    # Ensure non-empty and valid
    if not regex:
        regex = ".+"
    return regex

def build_input_for(regex: str, rng: random.Random) -> str:
    # Heuristic: craft input that often matches the regex
    # Generate a base by sampling alnum and spaces, plus words likely in regex
    base = []
    # If we detect literal words in regex (between letters), include them
    literals = []
    cur = []
    for ch in regex:
        if ch.isalnum():
            cur.append(ch)
        else:
            if cur:
                lit = ''.join(cur)
                if len(lit) >= 2:
                    literals.append(lit)
                cur = []
    if cur:
        lit = ''.join(cur)
        if len(lit) >= 2:
            literals.append(lit)
    # Compose lines with literals and filler matching classes
    for _ in range(rng.randint(1, 3)):
        if rng.random() < 0.7 and literals:
            base.append(rng.choice(literals))
        # Add digits/word chars/space to satisfy common classes
        if rng.random() < 0.7:
            base.append(''.join(rng.choice(string.digits) for _ in range(rng.randint(0, 3))))
        if rng.random() < 0.7:
            base.append(''.join(rng.choice(string.ascii_letters + '_') for _ in range(rng.randint(1, 6))))
        if rng.random() < 0.5:
            base.append(rng.choice([" ", "\t", "\n"]))
    s = ''.join(base)
    if not s:
        s = rand_word(rng)
    # Keep it moderate length
    if len(s) > 256:
        s = s[:256]
    return s

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Create multiple regex/data pairs to fuel numerous FUZZ_PARAM_STR() calls
    pairs = []
    count = rng.randint(4, 10)
    for _ in range(count):
        rx = build_regex(rng)
        data = build_input_for(rx, rng)
        pairs.append(rx)
        pairs.append(data)
    # Also add some very simple safe regexes used by specific stubs
    basics = [".+", "(a+)?(b+)?c+", "(x+)?(y+)?z+", "^\w+\s+\d+$", "^.*$", "^a{0,3}b{2,5}c$"]
    for b in basics:
        pairs.append(b)
        pairs.append(build_input_for(b, rng))
    # Join with newlines so each FUZZ_PARAM_STR() can consume a chunk
    blob = "\n".join(pairs)
    # Ensure UTF-8 validity: our construction uses Python strs; encode to utf-8
    data = blob.encode('utf-8', errors='strict')
    # Clip to max size constraint
    if len(data) > 4096:
        data = data[:4096]
    return data
